const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const lp=(a,b,t)=>a+(b-a)*t;
const W=width, Hh=height, u=Math.min(W,Hh);
