const eAmp=P.energy*(.4+.75*K.intensity);
S.tre=(S.tre||0)*.82+(A.treble||0)*.18; S.bass=(S.bass||0)*.8+(A.bass||0)*.2;
const tre=S.tre, bass=S.bass;
const waterY=Hh*0.66;
const dB=Math.round(dens*4);

function pal(){
  if(st==='noir') return {sky:[0,0,11],skyTop:[0,0,4],bld:[0,0,10],bld2:[0,0,17],win:[0,0,92],winD:[0,0,42],sign:[0,0,82],rain:[0,0,100]};
  if(st==='thermal') return {sky:[268,60,14],skyTop:[278,70,7],bld:[232,68,30],bld2:[210,58,44],win:[46,92,100],winD:[22,82,72],sign:[8,92,100],rain:[200,45,88]};
  if(st==='riso') return {sky:[192,58,20],skyTop:[200,62,11],bld:[192,72,40],bld2:[192,78,56],win:[330,72,92],winD:[330,48,58],sign:[332,84,96],rain:[192,26,95]};
  return {sky:[242,58,12],skyTop:[252,66,6],bld:[250,42,15],bld2:[256,38,24],win:[45,58,96],winD:[35,48,52],sign:[H,82,98],rain:[204,22,96]};
}
const C=pal();

// ── bake skyline into buffer ─────────────────────────────
if(!S.city || S.cKey!==W+'x'+Hh+st+P.seed+dB){
  const g=createGraphics(W, Math.max(2,Math.round(waterY)));
  g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  const gw=W, gh=Math.round(waterY);
  // sky gradient
  for(let i=0;i<40;i++){ const v=i/40; g.fill(lp(C.skyTop[0],C.sky[0],v), lp(C.skyTop[1],C.sky[1],v), lp(C.skyTop[2],C.sky[2],v)); g.rect(0,v*gh,gw+1,gh/40+1.5); }
  // horizon glow band
  g.blendMode(g.ADD); for(let i=0;i<6;i++){ g.fill(st==='thermal'?15:H, st==='noir'?0:40, 100, 5); g.ellipse(gw*0.5, gh, gw*(1.1-i*0.12), gh*(0.5-i*0.05)); } g.blendMode(g.BLEND);
  const signs=[];
  const nB=6+dB*7;
  // buildings sorted back(smaller) to front(taller)
  const blds=[];
  for(let i=0;i<nB;i++){ blds.push({x:fr(i*3)*gw, w:gw*(0.05+fr(i*3+1)*0.11), h:gh*(0.28+fr(i*3+2)*0.62), depth:fr(i*3+2)}); }
  blds.sort((a,b)=>a.h-b.h);
  for(let bi=0;bi<blds.length;bi++){ const b=blds[bi]; const bx=b.x-b.w/2, by=gh-b.h;
    const dep=bi/blds.length; g.fill(lp(C.bld[0],C.bld2[0],dep), lp(C.bld[1],C.bld2[1],dep), lp(C.bld[2],C.bld2[2],dep));
    g.rect(bx,by,b.w,b.h+2);
    // window grid
    const cols=Math.max(2,Math.floor(b.w/(u*0.028))), rows=Math.max(3,Math.floor(b.h/(u*0.05)));
    const cw=b.w/cols, rh=b.h/rows;
    for(let cx=0;cx<cols;cx++) for(let ry=0;ry<rows;ry++){ const idx=bi*991+cx*37+ry*7; const on=fr(idx)>0.42;
      const wx=bx+cx*cw+cw*0.22, wy=by+ry*rh+rh*0.2, ww=cw*0.56, wh=rh*0.58;
      if(on){ g.fill(C.win[0], C.win[1], C.win[2], 92); } else { g.fill(C.winD[0],C.winD[1],C.winD[2],55); }
      g.rect(wx,wy,ww,wh); }
    // rooftop neon sign on some tall buildings
    if(b.h>gh*0.5 && fr(bi*13+5)>0.45){ const sw=b.w*(0.5+fr(bi+2)*0.4), sh=Math.max(6,rh*0.9); const sx=bx+b.w/2-sw/2, sy=by-sh*1.3;
      signs.push({x:sx,y:sy,w:sw,h:sh, hue:(fr(bi*17)*360), ph:fr(bi*19)*6.283, glyphs:2+Math.floor(fr(bi*23)*4)});
      g.fill(st==='thermal'?8:(st==='noir'?0:fr(bi*17)*360), st==='noir'?0:80, 30); g.rect(sx-2,sy-2,sw+4,sh+4);
    }
  }
  S.city=g; S.cKey=W+'x'+Hh+st+P.seed+dB; S.signs=signs;
  // dot-matrix mask
  if(st==='dotmatrix'){ const m=createGraphics(W,Hh); m.colorMode(m.HSB,360,100,100,100); m.background(0,0,0,100);
    const cell=Math.max(4,u*0.012); m.noStroke();
    m.erase(); for(let y=cell/2;y<Hh;y+=cell) for(let x=cell/2;x<W;x+=cell){ m.circle(x,y,cell*0.84);} m.noErase(); S.mask=m; }
}

