image(S.city,0,0);
// reflection
push(); translate(0, waterY*2); scale(1,-1); tint(0,0,100, st==='noir'?38:46); image(S.city,0,0); noTint(); pop();
// water veil + shimmer
noStroke(); fill(st==='thermal'?265:(st==='noir'?0:230), st==='noir'?0:55, st==='noir'?6:9, 62); rect(0,waterY,W,Hh-waterY);
blendMode(ADD);
for(let i=0;i<12;i++){ const yy=waterY+((i/12)+((K.t*0.06)%(1/12)))*(Hh-waterY); const fl=0.4+0.6*Math.abs(Math.sin(K.t*2.2+i*1.3+fr(i)));
  fill(st==='noir'?0:H, st==='noir'?0:35, 100, 4*fl+tre*14*fl); rect(0, yy, W, (Hh-waterY)*0.04); }
blendMode(BLEND);

// ── sign flicker (live glow) ──
if(S.signs){ blendMode(ADD); noStroke();
  for(const s of S.signs){ const fk=0.55+0.45*Math.sin(K.t*7+s.ph) + (fr(Math.floor(K.t*3)+s.ph)>0.85?-0.5:0);
    const a=Math.max(0, fk)*(18+P.glow*20)+bass*20;
    const sh=st==='noir'?0:(st==='thermal'?8:(st==='tokyo'?H:s.hue));
    fill(sh, st==='noir'?0:80, 100, a); rect(s.x-3,s.y-3,s.w+6,s.h+6);
    // abstract glyph ticks
    fill(sh, st==='noir'?0:20, 100, a*1.3);
    for(let gI=0;gI<s.glyphs;gI++){ const gx=s.x+ (gI+0.5)/s.glyphs*s.w; rect(gx-s.w*0.06, s.y+s.h*0.2, s.w*0.12, s.h*0.6); }
  }
  blendMode(BLEND);
}

// ── RAIN (continuous real-time fall) ──
const stormy=P.act==='storm', drizz=P.act==='drizzle';
const nR=Math.min(340, Math.round((drizz?30:70)+dens*220+(stormy?90:0)));
const slant=(P.wind*1.3+ (stormy?0.5:0))* (0.6+eAmp);
const fall=u*(1.1+eAmp*0.9)*(drizz?0.7:1);
strokeCap(ROUND);
for(let i=0;i<nR;i++){ const sx=fr(i*2)*W*1.2-W*0.1; const spd=0.6+fr(i*2+1)*0.8; const len=u*(0.02+fr(i+3)*0.035)*(drizz?0.6:1);
  let y=(fr(i+7)*Hh + K.t*fall*spd)%(Hh+len)-len; const x=sx + (y/Hh)*slant*u*0.25 + K.t*slant*u*0.02;
  const a=st==='noir'?60:44; stroke(C.rain[0],C.rain[1],C.rain[2], a+tre*20); strokeWeight(lp(0.8,1.8,fr(i+11)));
  line(x,y, x+slant*len*0.5, y+len); }
noStroke();
// splash ripples near water
blendMode(ADD);
for(let i=0;i<Math.round(6+dens*10);i++){ const rx=fr(i*5+50)*W; const ph=(K.t*1.4+fr(i+60)*3)%1; const rr=ph*u*0.03;
  stroke(C.rain[0],C.rain[1],C.rain[2], (1-ph)*30); strokeWeight(1); noFill(); ellipse(rx, waterY+fr(i+61)*(Hh-waterY)*0.5, rr*2, rr*0.6); }
noStroke(); blendMode(BLEND);

// ── lightning (act storm) — PARTIAL frame only ──
if(stormy){ const seg=Math.floor(K.t*0.5); const trig=fr(seg*7+3); const local=(K.t*0.5)%1;
  if(trig>0.72 && local<0.14){ const fa=(1-local/0.14); blendMode(ADD);
    noStroke(); fill(st==='thermal'?200:210, st==='noir'?0:15, 100, 22*fa);
    const bx=fr(seg*11)*W; beginShape(); vertex(bx,0); let lx=bx; for(let y=0;y<waterY;y+=waterY/8){ lx+=(fr(seg+y)-0.5)*u*0.06; vertex(lx,y);} vertex(lx+u*0.03, waterY); vertex(lx-u*0.03,waterY); for(let y=waterY;y>0;y-=waterY/8){ vertex(lx,y);} endShape(CLOSE);
    // sky glow patch (partial, upper third)
    fill(210, st==='noir'?0:20, 100, 10*fa); rect(0,0,W,Hh*0.35);
    blendMode(BLEND); }
}

// ── dot-matrix mask overlay ──
if(st==='dotmatrix' && S.mask){ blendMode(MULTIPLY); image(S.mask,0,0); blendMode(BLEND);
  // scanline drift
  blendMode(ADD); noStroke(); fill(H,40,100, 6); const sy=(K.t*u*0.1)%Hh; rect(0,sy,W,u*0.01); blendMode(BLEND); }

blendMode(BLEND); noStroke();
